#!/usr/bin/env python3
# Step 2: classify every Bash call of every worker, link detached runs to their ends, and print the
# tables.  Run: python3 -I measure.py   (reads extract.pkl made by extract.py)
# Prints only counts, times and command lines (never message text).
import os, sys, re, math, pickle, collections, json, glob

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import classify as C

A = pickle.load(open(os.path.join(HERE, 'extract.pkl'), 'rb'))


# ---------------------------------------------------------------- helpers
def pct(xs, p):
    """nearest-rank percentile"""
    if not xs:
        return float('nan')
    s = sorted(xs)
    k = max(1, math.ceil(p / 100.0 * len(s)))
    return s[k - 1]


def med(xs):
    if not xs:
        return float('nan')
    s = sorted(xs)
    n = len(s)
    return s[n // 2] if n % 2 else (s[n // 2 - 1] + s[n // 2]) / 2


def fmt(x):
    if x != x:
        return '-'
    if x >= 100:
        return '%.0f' % x
    if x >= 10:
        return '%.1f' % x
    return '%.2f' % x


def hms(sec):
    sec = int(round(sec))
    return '%dh%02dm' % (sec // 3600, sec % 3600 // 60)


def flat(cmd, n=150):
    return re.sub(r'\s+', ' ', cmd).strip()[:n]


# ---------------------------------------------------------------- roles
def role_of(a):
    d = (a['desc'] or '').lower()
    p = (a['first_prompt'] or '')[:400].lower()
    s = d
    if re.search(r'^rung|\brung\b', s):
        return 'rung worker'
    if 'skeptic' in s:
        return 'skeptic'
    if re.search(r'probe|checker-speed|trial', s):
        return 'probe'
    if re.search(r'gather|scout|archaeolog|research|\bmap\b|route|ways', s):
        return 'gather'
    if re.search(r'\bplan|design|outline|triage', s):
        return 'planner'
    if re.search(r'review|cold ?read|judge|grade|reader|fact-check|audit|verify|re-read|post-batch', s):
        return 'review'
    if re.search(r'^gate|\bgate\b|commit|\bland\b', s):
        return 'gate/commit'
    if re.search(r'measure|time|score', s):
        return 'measure'
    if re.search(r'write|facts|record|consolidat|draft|fold|update|apply|amend|rewrite|revise|assemble|summarize|fix|bring|repoint|make|add|sort|file|fix', s):
        return 'writer/record'
    # fall back on the first prompt's own role words
    if 'probe' in p:
        return 'probe'
    if re.search(r'archaeolog|scout|research', p):
        return 'gather'
    if 'skeptic' in p:
        return 'skeptic'
    if re.search(r'cold reader|judge|checker', p):
        return 'review'
    if 'planning' in p:
        return 'planner'
    return 'other'


# ---------------------------------------------------------------- scripts
written = collections.defaultdict(list)  # basename -> [(t, ai, body)]
for ai, a in enumerate(A):
    for c in a['calls']:
        for p, body in C.written_scripts(c['cmd']):
            written[os.path.basename(p)].append((c['t0'], ai, body))
    for (t, p, body) in a['writes']:
        written[os.path.basename(p)].append((t, ai, body))
for k in written:
    written[k].sort(key=lambda x: x[0] or 0)

disk = collections.defaultdict(list)
for root in ['/home/user']:
    for dp, dn, fn in os.walk(root):
        if any(x in dp for x in ('/node_modules', '/.git', '/build', '/default_repository', '/caches')):
            dn[:] = []
            continue
        for f in fn:
            if f.endswith('.sh'):
                disk[f].append(os.path.join(dp, f))
for dp, dn, fn in os.walk('/tmp/claude-0'):
    for f in fn:
        if f.endswith('.sh') and '/measure-commands' not in dp:
            disk[f].append(os.path.join(dp, f))

AMBIG = {'run.sh', 'a.sh', 'x.sh', 'test.sh', 'go.sh'}
res_stats = collections.Counter()


def resolve_script(name, raw, ai, t):
    # 1 same agent, latest before t
    best = None
    for (tw, aw, body) in written.get(name, []):
        if aw == ai and tw is not None and t is not None and tw <= t:
            best = body
    if best is not None:
        res_stats['same-agent'] += 1
        return best
    if name not in AMBIG:
        for (tw, aw, body) in written.get(name, []):
            if tw is not None and t is not None and tw <= t:
                best = body
        if best is not None:
            res_stats['other-agent'] += 1
            return best
    cands = disk.get(name, [])
    if cands:
        want = raw.lstrip('./')
        pick = None
        for pth in cands:
            if pth.endswith(want):
                pick = pth
                break
        if pick is None and name not in AMBIG:
            pick = cands[0]
        if pick:
            try:
                res_stats['disk'] += 1
                return open(pick, errors='replace').read()[:60000]
            except Exception:
                pass
    res_stats['unresolved'] += 1
    return None


def expand(cmd, ai, t, depth=0, seen=()):
    """invocations of cmd with scripts replaced by their bodies' invocations.
    -> (list of invocation tuples, list of unresolved script names, text that was scanned)"""
    out = []
    unres = []
    texts = [cmd]
    for v in C.invocations(cmd):
        if v[0] == 'script':
            name, raw = v[1], v[2]
            body = None if (depth >= 3 or name in seen) else resolve_script(name, raw, ai, t)
            if body is None:
                unres.append(name)
                continue
            o, u, tx = expand(body, ai, t, depth + 1, seen + (name,))
            out += o
            unres += u
            texts += tx
        else:
            out.append(v)
    return out, unres, texts


LOOP = re.compile(r'\b(for|while)\b[^\n;]*[;\n]\s*do\b|\bxargs\b|-exec\b|\bparallel\b')

# ---------------------------------------------------------------- enrich calls
HEAVY = ('c', 'b', 'a')
for ai, a in enumerate(A):
    a['role'] = role_of(a)
    for ci, c in enumerate(a['calls']):
        c['ai'] = ai
        c['ci'] = ci
        c['wall'] = (c['t1'] - c['t0']) if (c['t1'] is not None and c['t0'] is not None) else None
        inv, unres, texts = expand(c['cmd'], ai, c['t0'])
        c['inv'] = inv
        c['unres'] = unres
        kinds = set()
        for v in inv:
            k = v[0]
            if k in ('fortress', 'harness-one', 'junit.sh', 'java'):
                kinds.add('a')
            elif k == 'ant':
                kinds.add('b')
            elif k == 'stage':
                kinds.add('c')
        c['kinds'] = kinds
        c['cls'] = next((k for k in HEAVY if k in kinds), 'd')
        c['mixed'] = len(kinds) > 1
        c['n_a'] = sum(1 for v in inv if v[0] in ('fortress', 'harness-one', 'junit.sh', 'java'))
        c['loopy'] = bool(c['n_a']) and any(LOOP.search(tx) for tx in texts)
        c['wait_logs'] = [v[1] for v in inv if v[0] == 'wait_for' and not v[1].startswith(('(', '{'))]
        c['detached'] = C.is_detached(c['cmd'], c['bg']) and bool(kinds)
        c['logs'] = C.log_paths(c['cmd']) if c['detached'] else set()
        c['via_script'] = any(v[0] == 'script' for v in C.invocations(c['cmd']))
        c['pure_wait'] = (not kinds) and (bool(c['wait_logs']) or
                                          bool(re.search(r'\bsleep\s+\d', c['cmd']) and len(c['cmd']) < 600) or
                                          bool(re.search(r'\buntil\b.*\bsleep\b', c['cmd'])))

# ---------------------------------------------------------------- link detached runs
link_stats = collections.Counter()
for ai, a in enumerate(A):
    calls = a['calls']
    for c in calls:
        c['poll_of'] = None
        c['run'] = None
    for ci, c in enumerate(calls):
        if not c['detached']:
            continue
        run = dict(launch=c, end=None, how=None, polls=[])
        c['run'] = run
        if c['bg'] or c['bgmsg']:
            if c['note']:
                run['end'] = c['note'][0]
                run['how'] = 'notified'
            else:
                run['how'] = 'bg-unmatched'
        else:
            logs = {os.path.basename(x) for x in c['logs']}
            if logs:
                for cj in range(ci + 1, len(calls)):
                    d = calls[cj]
                    if d['t1'] is None:
                        continue
                    mention = any(lg in d['cmd'] for lg in logs)
                    if mention and d['has_exit']:
                        run['end'] = d['t1']
                        run['how'] = 'wait_for' if d['wait_logs'] else 'polled'
                        break
                if run['end'] is not None:
                    for cj in range(ci + 1, len(calls)):
                        d = calls[cj]
                        if d['t1'] is not None and d['t1'] <= run['end'] + 0.001 and d['poll_of'] is None \
                                and not d['kinds'] and (d['wait_logs'] or any(lg in d['cmd'] for lg in logs)) \
                                and (d['wait_logs'] or d['pure_wait']):
                            d['poll_of'] = run
                            run['polls'].append(d)
                else:
                    run['how'] = 'unmatched'
            else:
                run['how'] = 'no-log'
        link_stats[run['how']] += 1
        # the launch call itself may hold a wait (define + launch + wait in one call)
    # waits that follow with a still-running verdict but no EXIT: attach to the latest unfinished run by log
    for ci, c in enumerate(calls):
        if c['pure_wait'] and c['poll_of'] is None and c['wait_logs']:
            lg = os.path.basename(c['wait_logs'][0])
            for cj in range(ci - 1, -1, -1):
                r = calls[cj].get('run')
                if r and any(os.path.basename(x) == lg for x in calls[cj]['logs']):
                    c['poll_of'] = r
                    r['polls'].append(c)
                    break

# ---------------------------------------------------------------- logical calls
logical = []   # one per non-poll call
for a in A:
    for c in a['calls']:
        if c['wall'] is None or c['poll_of'] is not None:
            continue
        L = dict(call=c, cls=c['cls'], mixed=c['mixed'], agent=c['ai'], naive=c['wall'], blocked=c['wall'],
                 span=None, how=None)
        r = c['run']
        if r is not None:
            L['blocked'] = c['wall'] + sum(p['wall'] for p in r['polls'])
            L['how'] = r['how']
            if r['end'] is not None and c['t1'] is not None:
                L['span'] = max(0.0, r['end'] - c['t1']) + c['wall']
        logical.append(L)

# ---------------------------------------------------------------- statistics
out = []


def P(s=''):
    out.append(s)
    print(s)


all_calls = [c for a in A for c in a['calls']]
timed = [c for c in all_calls if c['wall'] is not None]
P('## raw counts')
P('agents %d (top-level %d, workflow %d); Bash calls %d; with a result %d; without %d' % (
    len(A), sum(1 for a in A if not a['workflow']), sum(1 for a in A if a['workflow']),
    len(all_calls), len(timed), len(all_calls) - len(timed)))
P('background-flag calls %d; detached runs (nohup/&/bg) with a Fortress/ant/stage command %d; link result %s' % (
    sum(1 for c in all_calls if c['bg']), sum(1 for c in all_calls if c['detached']), dict(link_stats)))
P('script resolution %s' % dict(res_stats))
neg = [c for c in timed if c['wall'] < 0]
huge = [c for c in timed if c['wall'] > 3600]
P('negative walls %d; walls over 1 h %d: %s' % (len(neg), len(huge), [round(c['wall']) for c in huge]))

# --- table 1: naive per-call classes (the brief's step 2/3 literally)
P()
P('## table N: class by each call\'s own command line (detached launches ~0 s, wait_for polls in d)')
for cls in ('a', 'b', 'c', 'd'):
    ws = [c['wall'] for c in timed if c['cls'] == cls]
    P('%s n=%d total=%.0fs (%s) median=%s p90=%s' % (cls, len(ws), sum(ws), hms(sum(ws)), fmt(med(ws)), fmt(pct(ws, 90))))
wd = [c['wall'] for c in timed if c['cls'] == 'd' and c['pure_wait']]
